{
  "name": "magpie-lobsterai-auth",
  "version": "0.2.2",
  "description": "Unofficial OpenCode / Magpie provider plugin for NetEase Youdao LobsterAI (有道龙虾): browser sign-in, live plan models, token refresh and credit usage.",
  "type": "module",
  "main": "./index.mjs",
  "exports": {
    ".": "./index.mjs"
  },
  "files": [
    "index.mjs",
    "lib",
    "CHANGELOG.md",
    "README.md",
    "README.en.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-provider",
    "magpie",
    "magpie-plugin",
    "lobsterai",
    "auth",
    "youdao",
    "netease",
    "provider",
    "ai-provider",
    "coding-plan"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/BowlongRise/magpie-lobsterai-auth.git"
  },
  "homepage": "https://github.com/BowlongRise/magpie-lobsterai-auth#readme",
  "bugs": {
    "url": "https://github.com/BowlongRise/magpie-lobsterai-auth/issues"
  },
  "publishConfig": {
    "registry": "https://registry.npmjs.org/"
  },
  "engines": {
    "node": ">=20.3"
  },
  "scripts": {
    "test": "node --test",
    "check": "node --check index.mjs && node --check lib/auth.mjs && node --check lib/catalog.mjs && node --check lib/checkin.mjs && node --check lib/constants.mjs && node --check lib/request.mjs && node --check lib/usage.mjs && node --check lib/util.mjs"
  },
  "magpie": {
    "name": "LobsterAI",
    "icon": "https://raw.githubusercontent.com/netease-youdao/LobsterAI/main/public/logo.png",
    "summary": {
      "en": "NetEase Youdao LobsterAI (有道龙虾) with the account's browser sign-in: live plan models, reasoning levels, token renewal and credit usage. Unofficial.",
      "zh": "网易有道 LobsterAI（有道龙虾）账号浏览器登录：动态套餐模型、思考档位、Token 续期与积分用量。非官方。"
    },
    "maxConcurrency": 4
  }
}
